INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('1b4be59c3019ea3fc50ea9fe015a7ec0', 'JEEMains', '11', 'Mathematics', 'math_11_jm_permutations_combinations', 'P and C', 'Factorial notation permutation nPr', '[]', '["Factorial Notation","Permutation","Combination"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, 'Find the value of $n$ in the expression $n! = 100$.', '["$4$", "$5$", "$6$", "$7$"]', '$5$', 'Step 1: Recall the definition of factorial notation $n! = n \times (n-1) \times (n-2) \times \text{…} \times 2 \times 1$.,Step 2: Plug in the value of $n! = 100$ into the definition to get the value of $n$.', '["Step 1: Recall the definition of factorial notation $n! = n \times (n-1) \times (n-2) \times \text{…} \times 2 \times 1$.", "Step 2: Plug in the value of $n! = 100$ into the definition to get the value of $n$."]', '$n! = n 	imes (n-1) 	imes (n-2) 	imes 	ext{…} 	imes 2 	imes 1$', 'math.permutations_combinations.factorial', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:00.166Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('1b51adbd6085deb10586c674de8d23a5', 'JEEMains', '12', 'Mathematics', 'math_12_jm_determinants', 'Determinants', 'Area of triangle using determinants', '[]', '["determinant","area of triangle","coordinate geometry","matrix method"]', 0, 0, '[]', 'MCQ', NULL, 0, 1880, 'JEE_MAINS_EASY', 3, -1.0, 'The vertices of a triangle are \(A(2,3)\), \(B(5,7)\) and \(C(8,3)\). Find its area using determinants.', '["12 sq units", "10 sq units", "14 sq units", "8 sq units"]', '12 sq units', 'Using the determinant formula \(\text{Area}=\frac12|x_1(y_2-y_3)+x_2(y_3-y_1)+x_3(y_1-y_2)|\) gives \(\frac12| -24| = 12\).', '["Step 1: Write the determinant \\(\\begin{vmatrix}2&3&1\\\\5&7&1\\\\8&3&1\\end{vmatrix}\\).", "Step 2: Evaluate the determinant to get \\(-24\\).", "Step 3: Take absolute value and multiply by \\(\\frac12\\) to obtain the area \\(12\\)."]', 'Area = \frac12|x_1(y_2-y_3)+x_2(y_3-y_1)+x_3(y_1-y_2)|', 'math.geometry.determinant_area_sign', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:46:28.842Z', -1);
